import sys
from typing import List, Tuple

def expected_time_to_set_record(n: int, r: int, tricks: List[Tuple[int, float, int]]) -> float:
    def dp(i: int, t: int) -> float:
        if i == len(tricks):
            return max(t, n)
        else:
            t_success = dp(i + 1, t + tricks[i][0])
            t_fail = dp(i + 1, t + tricks[i][0] + tricks[i][2])
            return min(t_success * tricks[i][1] + t_fail * (1 - tricks[i][1]), n)

    return dp(0, 0)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    r = int(data[1])
    m = int(data[2])

    tricks = []
    index = 3
    for _ in range(m):
        t = int(data[index])
        p = float(data[index + 1])
        d = int(data[index + 2])
        tricks.append((t, p, d))
        index += 3

    result = expected_time_to_set_record(n, r, tricks)
    print(f"{result:.6f}")

if __name__ == "__main__":
    main()
